// ============================================================
// app/ui-savegame.js
// Savegame view: read a FOUNDRY save file in the browser and show
// statistics by category. Format: see read_savegame.py.
//   header → section directory → zstd-compressed MessagePack sections.
// Template references are 64-bit hashes; names come from SAVE_TEMPLATES
// (generated by extract_game_data.py). Fields *_fpm are fixed point × 10,000.
// Needs fzstd (zstd decoder, loaded in index.html).
// ============================================================

const _SAVE_FPM = 10000;
const _SAVE_TICKS_PER_SEC = 60;
// Sections not needed for statistics (terrain ~180 MB, world decor ~70 MB):
// recognised from the first decompressed bytes and skipped.
const _SAVE_SKIP_MARKERS = ['bin_terrainData', 'ticksGrown'];
const _SAVE_STOP = {};

let _saveStats = null;

// ── Templates ────────────────────────────────────────────────
function _saveTpl(id) {
  return (id && typeof SAVE_TEMPLATES !== 'undefined') ? SAVE_TEMPLATES[String(id)] || null : null;
}
function _saveName(id) {
  const t = _saveTpl(id);
  return t ? t[1] : (id ? '#' + id : null);
}

// ── MessagePack (only decoding; uint64/int64 beyond 2^53 stay BigInt) ──
function _mpDecode(buf) {
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const td = new TextDecoder();
  let p = 0;
  const big = x => (x <= 9007199254740991n && x >= -9007199254740991n) ? Number(x) : x;
  const str = n => { const s = td.decode(buf.subarray(p, p + n)); p += n; return s; };
  const bin = n => { const b = buf.subarray(p, p + n); p += n; return b; };
  const arr = n => { const a = new Array(n); for (let i = 0; i < n; i++) a[i] = rd(); return a; };
  const map = n => { const o = {}; for (let i = 0; i < n; i++) { const k = rd(); o[String(k)] = rd(); } return o; };
  const ext = n => { p += 1 + n; return null; };
  function rd() {
    const b = buf[p++];
    if (b < 0x80) return b;
    if (b < 0x90) return map(b & 0x0f);
    if (b < 0xa0) return arr(b & 0x0f);
    if (b < 0xc0) return str(b & 0x1f);
    if (b >= 0xe0) return b - 256;
    let v;
    switch (b) {
      case 0xc0: return null;
      case 0xc2: return false;
      case 0xc3: return true;
      case 0xc4: return bin(buf[p++]);
      case 0xc5: v = dv.getUint16(p); p += 2; return bin(v);
      case 0xc6: v = dv.getUint32(p); p += 4; return bin(v);
      case 0xc7: v = buf[p++]; return ext(v);
      case 0xc8: v = dv.getUint16(p); p += 2; return ext(v);
      case 0xc9: v = dv.getUint32(p); p += 4; return ext(v);
      case 0xca: v = dv.getFloat32(p); p += 4; return v;
      case 0xcb: v = dv.getFloat64(p); p += 8; return v;
      case 0xcc: return buf[p++];
      case 0xcd: v = dv.getUint16(p); p += 2; return v;
      case 0xce: v = dv.getUint32(p); p += 4; return v;
      case 0xcf: v = dv.getBigUint64(p); p += 8; return big(v);
      case 0xd0: v = dv.getInt8(p); p += 1; return v;
      case 0xd1: v = dv.getInt16(p); p += 2; return v;
      case 0xd2: v = dv.getInt32(p); p += 4; return v;
      case 0xd3: v = dv.getBigInt64(p); p += 8; return big(v);
      case 0xd4: return ext(1);
      case 0xd5: return ext(2);
      case 0xd6: return ext(4);
      case 0xd7: return ext(8);
      case 0xd8: return ext(16);
      case 0xd9: return str(buf[p++]);
      case 0xda: v = dv.getUint16(p); p += 2; return str(v);
      case 0xdb: v = dv.getUint32(p); p += 4; return str(v);
      case 0xdc: v = dv.getUint16(p); p += 2; return arr(v);
      case 0xdd: v = dv.getUint32(p); p += 4; return arr(v);
      case 0xde: v = dv.getUint16(p); p += 2; return map(v);
      case 0xdf: v = dv.getUint32(p); p += 4; return map(v);
    }
    throw new Error('msgpack: unknown byte 0x' + b.toString(16) + ' at ' + (p - 1));
  }
  return rd();
}

// ── Save container ───────────────────────────────────────────
// Returns [[offset, size], …] of the compressed sections.
function _saveSections(bytes) {
  if (new TextDecoder().decode(bytes.subarray(0, 7)) !== 'FOUNDRY') throw new Error('Not a FOUNDRY savegame');
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const n = dv.getUint32(0x40, true);
  let base = 0;
  for (let i = 0; i < n; i++) {
    const e = 0x44 + i * 12;
    base = Math.max(base, dv.getUint32(e + 4, true) + dv.getUint32(e + 8, true));
  }
  const count = dv.getUint32(base + 4, true);
  const out = [];
  for (let i = 0; i < count; i++) {
    const e = base + 8 + i * 16;
    out.push([base + dv.getUint32(e + 8, true), dv.getUint32(e + 12, true)]);
  }
  return out;
}

// Decompresses one section; null when it is a skipped one (see markers).
function _saveInflate(comp) {
  const chunks = [];
  let total = 0, checked = false;
  const d = new fzstd.Decompress(chunk => {
    if (!checked) {
      checked = true;
      const head = new TextDecoder('latin1').decode(chunk.subarray(0, 400));
      if (_SAVE_SKIP_MARKERS.some(m => head.includes(m))) throw _SAVE_STOP;
    }
    chunks.push(chunk);
    total += chunk.length;
  });
  const STEP = 1 << 18;
  try {
    for (let p = 0; p < comp.length; p += STEP) d.push(comp.subarray(p, Math.min(comp.length, p + STEP)), p + STEP >= comp.length);
  } catch (e) {
    if (e === _SAVE_STOP) return null;
    throw e;
  }
  if (chunks.length === 1) return chunks[0];
  const out = new Uint8Array(total);
  let o = 0;
  for (const c of chunks) { out.set(c, o); o += c.length; }
  return out;
}

function _saveEntityBase(e) {
  if (!e || typeof e !== 'object') return null;
  return e.BuildableEntityData || (e.ModularEntityBaseData && e.ModularEntityBaseData.BuildableEntityData) || null;
}

// ── Statistics ───────────────────────────────────────────────
function _saveCollect(obj, s) {
  if (Array.isArray(obj)) {
    const first = obj[0];
    if (!first || typeof first !== 'object') return;

    if ('energySatisfactionLevel' in first && 'battery_capacity_kj' in first) {
      const kw = _SAVE_TICKS_PER_SEC / _SAVE_FPM;
      for (const g of obj) {
        if (!g.energyRequestedPerTick && !g.battery_capacity_kj) continue;
        s.grids.push({
          satisfaction: g.energySatisfactionLevel / 100,
          demandKw: g.energyRequestedPerTick * kw,
          producerKw: g.maxTotalProducerOutputPerTick_current * kw,
          batteryKw: g.battery_delta_kj * kw,
          capacityKJ: g.battery_capacity_kj / _SAVE_FPM,
          chargeKJ: g.battery_storedCharge_kj / _SAVE_FPM,
          buildings: g.enabledBuildingsArray.reduce((a, b) => a + b, 0),
          disabled: g.disabledBuildingsArray.reduce((a, b) => a + b, 0),
        });
      }
      return;
    }
    if ('worldCellPos' in first && 'connectedMinerCount' in first) {
      for (const v of obj) {
        const ore = _saveName(v.templateId);
        const o = s.veins[ore] || (s.veins[ore] = { count: 0, miners: 0 });
        o.count++;
        o.miners += v.connectedMinerCount;
      }
      return;
    }
    if (!_saveEntityBase(first)) return;
    for (const e of obj) {
      const b = _saveEntityBase(e);
      const t = _saveTpl(b.buildableObjectTemplateId);
      const name = t ? t[1] : '#' + b.buildableObjectTemplateId;
      const cat = t ? t[3] : 'Unknown';
      const c = s.categories[cat] || (s.categories[cat] = { total: 0, items: {} });
      c.total++;
      c.items[name] = (c.items[name] || 0) + 1;
      s.buildings++;
      if (!b.isEnabled) s.disabled++;
      const rid = e.craftingRecipeId || e.craftingReceiptId || e.craftingModeTemplateId;
      if (rid) {
        const r = s.recipes[_saveName(rid)] || (s.recipes[_saveName(rid)] = {});
        r[name] = (r[name] || 0) + 1;
      }
    }
    return;
  }
  if (!obj || typeof obj !== 'object') return;
  if ('saveDataVersion' in obj) s.version = obj.saveDataVersion;
  if (obj.vec_pipeSegments) {
    for (const p of obj.vec_pipeSegments) {
      const fluid = _saveName(p.content_elementTemplateId) || '(empty)';
      const f = s.fluids[fluid] || (s.fluids[fluid] = { networks: 0, contentL: 0, capacityL: 0 });
      f.networks++;
      f.contentL += p.content_amount_l_fpm / _SAVE_FPM;
      f.capacityL += p.capacity_l_fpm / _SAVE_FPM;
    }
  }
  if (obj.umap_amountCompletedResearches) {
    for (const [id, n] of Object.entries(obj.umap_amountCompletedResearches)) {
      const t = _saveTpl(id);
      s.research++;
      if (t && t[2]) s.researchLevels[t[1]] = n;   // endless research: completions = level
      s.researchIds.push(id);
    }
    s.hardness = obj.unlockedMiningHardnessLevel;
  }
  if (obj.map_dataPerSalesItem) {
    // RDLabSystem (Main.dll): efficiency +2 %/point, weight −12.5 %/point, price +5 %/point
    for (const [id, v] of Object.entries(obj.map_dataPerSalesItem)) {
      if (!v.xpTotal) continue;
      s.rdLab[_saveName(id)] = {
        level: v.currentLevel, free: v.availableTechPoints,
        eff: v.spentTechPoints_efficiency * 2,
        weight: v.spentTechPoints_weight * 12.5,
        quality: v.spentTechPoints_quality * 5,
      };
    }
  }
}

async function loadSavegame(file) {
  const status = document.getElementById('saveStatus');
  const say = t => { if (status) status.textContent = t; };
  if (!file) return;
  if (typeof fzstd === 'undefined') { say('zstd decoder not loaded (no internet?).'); return; }
  if (typeof SAVE_TEMPLATES === 'undefined') { say('This game data version has no savegame support.'); return; }
  const t0 = performance.now();
  try {
    say('Reading ' + file.name + ' …');
    const bytes = new Uint8Array(await file.arrayBuffer());
    const sections = _saveSections(bytes);
    const s = {
      file: file.name, size: bytes.length, version: null, buildings: 0, disabled: 0,
      categories: {}, recipes: {}, grids: [], fluids: {}, veins: {},
      research: 0, researchIds: [], researchLevels: {}, rdLab: {}, hardness: null,
    };
    for (let i = 0; i < sections.length; i++) {
      say(`Reading section ${i + 1} / ${sections.length} …`);
      await new Promise(r => setTimeout(r, 0)); // keep the page responsive
      const [off, size] = sections[i];
      const raw = _saveInflate(bytes.subarray(off, off + size));
      if (raw) _saveCollect(_mpDecode(raw), s);
    }
    _saveStats = s;
    say(`${file.name} · ${(bytes.length / 1e6).toFixed(1)} MB · ${((performance.now() - t0) / 1000).toFixed(1)} s`);
    renderSavegame();
  } catch (e) {
    console.error(e);
    say('Error: ' + e.message);
  }
}

// ── Settings from the save ───────────────────────────────────
// Items locked behind a research (SAVE_TEMPLATES research entries list what
// they unlock); everything not listed there is available from the start.
function _saveAvailable(s) {
  const locked = new Set(), done = new Set();
  const doneIds = new Set(s.researchIds.map(String));
  for (const [id, t] of Object.entries(SAVE_TEMPLATES)) {
    if (t[0] !== 't' || !t[3]) continue;
    t[3].forEach(n => { locked.add(n); if (doneIds.has(id)) done.add(n); });
  }
  return name => !locked.has(name) || done.has(name);
}

// What the save would change: [{group, label, from, to, apply()}]
function _savePlan(s) {
  const ok = _saveAvailable(s);
  const plan = [];
  const add = (group, label, from, to, apply) => {
    if (String(from) !== String(to)) plan.push({ group, label, from, to, apply });
  };
  // Best unlocked tier per machine family (conveyor belt included)
  MACHINE_FAMILIES.forEach(f => {
    const best = f.machines.filter(ok).pop();
    const cur = f.defaultChoice || f.machines[0];
    if (best) add('Machines', f.label, cur, best, () => { f.defaultChoice = best; });
  });
  // Miner per raw item: the one built most in the save (drone miners and ore
  // vein miners work on different deposits, so "fastest" would be a guess)
  const built = {};
  Object.values(s.categories).forEach(c => Object.entries(c.items).forEach(([n, k]) => { built[n] = (built[n] || 0) + k; }));
  MINER_GROUPS.forEach(g => {
    const best = g.miners.filter(m => built[m]).sort((a, b) => built[b] - built[a])[0];
    const cur = minerSettings[g.label] || g.miners[0];
    if (best) add('Miners', g.label, cur, best, () => { minerSettings[g.label] = best; });
  });
  // Endless research levels
  [['Mining Efficiency', () => miningEfficiencyLevel, v => { miningEfficiencyLevel = v; }],
   ['Pumpjack Efficiency', () => pumpjackEfficiencyLevel, v => { pumpjackEfficiencyLevel = v; }]]
    .forEach(([name, get, set]) => {
      const lvl = s.researchLevels[name] || 0;
      add('Research', name, get(), lvl, () => set(lvl));
    });
  // R&D Lab per product (only products the calculator knows)
  Object.entries(s.rdLab).forEach(([name, v]) => {
    if (!RECIPES[name]) return;
    add('R&D efficiency', name, (botEfficiencyOverrides[name] ?? 0) + ' %', v.eff + ' %',
      () => { botEfficiencyOverrides[name] = v.eff; });
    add('R&D weight', name, '−' + (botWeightReductions[name] ?? 0) + ' %', '−' + v.weight + ' %',
      () => { botWeightReductions[name] = v.weight; });
  });
  return plan;
}

function applySavegameSettings() {
  if (!_saveStats) return;
  const plan = _savePlan(_saveStats);
  plan.forEach(p => p.apply());
  // Persist and re-render like a plan import
  saveSettings();
  buildRecipeCategoryList();
  renderSelectedRecipes();
  if (selectedRecipeList.length > 0) calculateRecipes();
  renderSavegame();
  const status = document.getElementById('saveStatus');
  if (status) status.textContent = `${plan.length} settings applied from ${_saveStats.file}`;
}

// ── Rendering ────────────────────────────────────────────────
function _saveTable(head, rows, numCols) {
  const th = head.map((h, i) => `<th${i >= head.length - numCols ? ' style="text-align:right"' : ''}>${h}</th>`).join('');
  const tr = rows.map(r => '<tr>' + r.map((c, i) =>
    `<td${i >= r.length - numCols ? ' class="num"' : ''}>${c}</td>`).join('') + '</tr>').join('');
  const thead = head.some(h => h) ? `<thead><tr>${th}</tr></thead>` : '';
  return `<table class="results-table">${thead}<tbody>${tr}</tbody></table>`;
}

function _saveSection(title, body) {
  return `<div style="margin-bottom:22px"><div class="section-title">${title}</div>${body}</div>`;
}

const _savePct = n => Math.round(n) + ' %';
function _saveKw(kw) {
  const a = Math.abs(kw);
  if (a < 0.5) return '–';
  const v = a >= 1000 ? fmt(Math.round(a / 100) / 10) + ' MW' : fmt(Math.round(a)) + ' kW';
  return (kw < 0 ? '−' : '') + v;
}

function renderSavegame() {
  const el = document.getElementById('saveContent');
  if (!el) return;
  const s = _saveStats;
  if (!s) {
    el.innerHTML = `<div style="color:var(--color-text-disabled);font-size:13px;padding:40px 0;text-align:center">
      Choose a savegame in the sidebar.</div>`;
    return;
  }
  const byCount = o => Object.entries(o).sort((a, b) => b[1] - a[1]);
  let html = '';

  // Settings the save would change in the calculator
  const plan = _savePlan(s);
  html += _saveSection('Use for calculator settings', plan.length ? `
    <div style="font-size:12px;color:var(--color-text-disabled);margin-bottom:8px">
      From completed research (best unlocked machine/conveyor tier), the miner built most,
      endless research levels and R&amp;D Lab points.</div>
    ${_saveTable(['Setting', '', 'Now', 'From save'],
      plan.map(p => [p.group, p.label, p.from, `<b>${p.to}</b>`]), 2)}
    <button onclick="applySavegameSettings()" class="nav-btn--active"
      style="margin-top:10px;padding:8px 16px;border:1px solid var(--color-border);border-radius:8px;cursor:pointer;font-size:13px;font-weight:600">
      Apply ${plan.length} settings</button>` :
    `<div style="font-size:13px;color:var(--color-text-disabled)">Calculator settings already match this save.</div>`);

  // Overview
  html += _saveSection('Overview', _saveTable(['', ''], [
    ['Buildings (incl. conveyors, pipes, blocks)', fmt(s.buildings)],
    ['Switched off', fmt(s.disabled)],
    ['Completed research', fmt(s.research)],
    ['Unlocked mining hardness', s.hardness != null ? fmt(s.hardness) : '-'],
    ['Save data version', s.version != null ? s.version : '-'],
  ], 1));

  // Buildings by category (collapsible, biggest category first)
  const cats = Object.entries(s.categories).sort((a, b) => b[1].total - a[1].total);
  html += _saveSection('Buildings by category', cats.map(([cat, c]) => `
    <details style="margin-bottom:6px">
      <summary style="cursor:pointer;padding:6px 2px;font-weight:600">${cat}
        <span style="float:right;font-variant-numeric:tabular-nums">${fmt(c.total)}</span></summary>
      ${_saveTable(['Building', 'Count'], byCount(c.items).map(([n, k]) => [n, fmt(k)]), 1)}
    </details>`).join(''));

  // Production: recipe → machines
  const recipes = Object.entries(s.recipes).map(([r, m]) => [r, Object.values(m).reduce((a, b) => a + b, 0), m])
    .sort((a, b) => b[1] - a[1]);
  html += _saveSection('Production (recipe set on machines)', _saveTable(['Recipe', 'Machines', 'Count'],
    recipes.map(([r, n, m]) => [r, byCount(m).map(([k, v]) => `${v}× ${k}`).join(', '), fmt(n)]), 1));

  // Power (snapshot at save time)
  html += _saveSection('Power grids <span style="font-weight:400;text-transform:none">(at save time)</span>',
    _saveTable(['Supply', 'Buildings', 'Demand', 'Generation', 'Battery', 'Charge'],
      s.grids.sort((a, b) => b.demandKw - a.demandKw).map(g => [
        _savePct(g.satisfaction),
        fmt(g.buildings) + (g.disabled ? ` (+${fmt(g.disabled)} off)` : ''),
        _saveKw(g.demandKw), _saveKw(g.producerKw),
        (g.batteryKw >= 0.5 ? '+' : '') + _saveKw(g.batteryKw),
        g.capacityKJ ? _savePct(g.chargeKJ / g.capacityKJ * 100) : '-',
      ]), 4));

  // Fluids in pipe networks
  html += _saveSection('Pipe networks', _saveTable(['Fluid', 'Networks', 'Content (L)', 'Capacity (L)', 'Fill'],
    Object.entries(s.fluids).sort((a, b) => b[1].capacityL - a[1].capacityL).map(([f, v]) => [
      f, fmt(v.networks), fmt(Math.round(v.contentL)), fmt(Math.round(v.capacityL)),
      v.capacityL ? _savePct(v.contentL / v.capacityL * 100) : '-',
    ]), 4));

  // Ore veins
  // ponytail: vein reserve not shown, miningProgressAvailableForConsumption is a buffer, not the reserve
  html += _saveSection('Ore veins', _saveTable(['Ore vein', 'Veins', 'Connected miners'],
    Object.entries(s.veins).sort((a, b) => b[1].count - a[1].count).map(([o, v]) => [
      o, fmt(v.count), fmt(v.miners),
    ]), 2));

  // Research
  html += _saveSection('Endless research', _saveTable(['Research', 'Level'],
    Object.entries(s.researchLevels).map(([r, n]) => [r, fmt(n)]), 1));
  html += _saveSection('R&amp;D Lab', _saveTable(['Product', 'Level', 'Free points', 'Efficiency', 'Weight', 'Price'],
    Object.entries(s.rdLab).sort((a, b) => b[1].level - a[1].level).map(([n, v]) => [
      n, fmt(v.level), fmt(v.free), '+' + fmt(v.eff) + ' %', '−' + fmt(v.weight) + ' %', '+' + fmt(v.quality) + ' %',
    ]), 5));

  el.innerHTML = html;
}
